local function clean(s)
    s = tostring(s or "")
    s = s:gsub("<[^>]*>", ""):gsub("&apos;", "'"):gsub("&quot;", '"')
        :gsub("&amp;", "&"):gsub("&lt;", "<"):gsub("&gt;", ">")
    return s
end

local function normalize(s)
    return clean(s):lower():gsub("’", "'"):gsub("'", "")
        :gsub("[^%w]+", " "):gsub("%s+", " "):match("^%s*(.-)%s*$")
end

local function questionPayload(s)
    local q = normalize(s)
    q = q:gsub("^sammy asks%s*", ""):gsub("^sammy says%s*", "")
    q = q:gsub("^the riddle is%s*", ""):gsub("^the riddle%s*", "")
    q = q:gsub("^riddle is%s*", ""):gsub("^riddle%s*", "")
    q = q:gsub("^question is%s*", ""):gsub("^question%s*", "")
    q = q:gsub("^what is%s+", ""):gsub("^whats%s+", "")
    q = q:gsub("^tell me%s+", ""):gsub("^the answer to%s+", "")
    q = q:gsub("^the%s+", "")
    return q
end

local function lookup(question)
    local q = questionPayload(question)
    if q == "" then return nil end
    local answer = RiddleDatabase[q]
    if answer then return tostring(answer) end

    -- Try common question prefixes and suffixes without guessing unrelated facts.
    local candidates = {
        q:gsub("^what is%s+", ""), q:gsub("^whats%s+", ""),
        q:gsub("^which is%s+", ""), q:gsub("^what%s+", ""),
        q:gsub("%s+trait$", ""), q:gsub("%s+brainrot$", "")
    }
    for _, candidate in ipairs(candidates) do
        candidate = candidate:match("^%s*(.-)%s*$")
        if RiddleDatabase[candidate] then return tostring(RiddleDatabase[candidate]) end
    end
    return nil
end

-- Minimal date resolver for common "today" questions.
local monthNames = {"january","february","march","april","may","june","july","august","september","october","november","december"}
local function dynamicAnswer(question)
    local q = questionPayload(question)
    local now = os.date("!*t")
    local map = {
        ["todays day"] = tostring(now.day), ["todays date"] = tostring(now.day),
        ["day today"] = tostring(now.day), ["date today"] = tostring(now.day),
        ["todays month"] = monthNames[now.month], ["month today"] = monthNames[now.month],
        ["todays year"] = tostring(now.year), ["year today"] = tostring(now.year),
    }
    return map[q]
end

local function getCodeControls()
    local codes = playerGui:FindFirstChild("Codes")
    if not codes then return nil end
    local nested = codes:FindFirstChild("Codes")
    if not nested then return nil end
    local redeem = nested:FindFirstChild("CodeRedeem")
    local box = redeem and redeem:FindFirstChild("TextBox")
    local confirm = nested:FindFirstChild("Confirm")
    if box and box:IsA("TextBox") and confirm and confirm:IsA("GuiButton") then
        return box, confirm
    end
end

local lastSubmitted = ""
local function submitAnswer(answer)
    if not AUTO_SUBMIT then return false, "Auto Submit desligado" end
    local box, confirm = getCodeControls()
    if not box then return false, "Codes UI não encontrada" end
    if not box.Active or not confirm.Active then return false, "A caixa de código não está pronta" end
    if lastSubmitted == answer then return false, "Resposta já enviada nesta sessão" end

    local old = box.Text
    box.Text = tostring(answer)
    if box.Text ~= tostring(answer) then
        box.Text = old
        return false, "Não foi possível preencher a caixa"
    end

    local ok = pcall(function()
        if typeof(firesignal) == "function" then
            firesignal(confirm.Activated)
        else
            confirm:Activate()
        end
    end)
    if not ok then
        box.Text = old
        return false, "Não foi possível ativar Confirm"
    end
    lastSubmitted = answer
    return true, "Resposta enviada: " .. answer
end

