local currentAnswer
local function solve(text, shouldSubmit)
    local answer = dynamicAnswer(text) or lookup(text)
    currentAnswer = answer
    answerBox.Text = answer or "NOT FOUND"
    if answer then
        status.Text = "Status: resposta encontrada no banco"
        if shouldSubmit and AUTO_SUBMIT then
            local ok, msg = submitAnswer(answer)
            status.Text = "Status: " .. msg
        end
    else
        status.Text = "Status: pergunta não encontrada"
    end
end

solveButton.MouseButton1Click:Connect(function() solve(questionBox.Text, false) end)
questionBox.FocusLost:Connect(function(enter)
    if enter then solve(questionBox.Text, false) end
end)
autoButton.MouseButton1Click:Connect(function()
    AUTO_SUBMIT = not AUTO_SUBMIT
    autoButton.Text = AUTO_SUBMIT and "AUTO SUBMIT: ON" or "AUTO SUBMIT: OFF"
    autoButton.BackgroundColor3 = AUTO_SUBMIT and Color3.fromRGB(35, 145, 85) or Color3.fromRGB(91, 66, 205)
    status.Text = AUTO_SUBMIT and "Status: auto submit ativado" or "Status: auto submit desligado"
end)
copyButton.MouseButton1Click:Connect(function()
    if currentAnswer and typeof(setclipboard) == "function" then
        pcall(setclipboard, tostring(currentAnswer))
        status.Text = "Status: resposta copiada"
