    end
end)

-- Drag window.
do
    local dragging, dragStart, startPos
    top.InputBegan:Connect(function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            dragging, dragStart, startPos = true, input.Position, main.Position
            input.Changed:Connect(function()
                if input.UserInputState == Enum.UserInputState.End then dragging = false end
            end)
        end
    end)
    UserInputService.InputChanged:Connect(function(input)
        if dragging and (input.UserInputType == Enum.UserInputType.MouseMovement or input.UserInputType == Enum.UserInputType.Touch) then
            local delta = input.Position - dragStart
            main.Position = UDim2.new(startPos.X.Scale, startPos.X.Offset + delta.X,
                startPos.Y.Scale, startPos.Y.Offset + delta.Y)
        end
    end)
end

-- Listen to Sammy's native announcement remote when available.
local function connectSammyRemote()
    local controllers = ReplicatedStorage:FindFirstChild("Controllers")
    local noticeModule = controllers and controllers:FindFirstChild("NotificationController")
    if not noticeModule then
        status.Text = "Status: aguardando NotificationController"
        return false
    end
    local ok, notification = pcall(require, noticeModule)
    if not ok or type(notification) ~= "table" or type(notification.Start) ~= "function" then
        status.Text = "Status: NotificationController indisponível"
        return false
    end
    if type(debug) ~= "table" or type(debug.getupvalues) ~= "function" then
        status.Text = "Status: executor sem debug.getupvalues"
        return false
    end
    local good, upvalues = pcall(debug.getupvalues, notification.Start)
    if not good then return false end
    local remote
    for _, value in pairs(upvalues) do
        if typeof(value) == "Instance" and value:IsA("RemoteEvent")
            and value:IsDescendantOf(ReplicatedStorage) then
            if remote and remote ~= value then
                status.Text = "Status: remote de anúncio ambíguo"
                return false
            end
            remote = value
        end
    end
    if not remote then
        status.Text = "Status: remote de anúncio não encontrado"
        return false
    end

    remote.OnClientEvent:Connect(function(message, duration, sound, location, sender, id, remove)
        if remove or location ~= "Top" or tonumber(sender) ~= SAMMY_USER_ID then return end
        if type(message) ~= "string" or #message > 500 then return end
        local q = normalize(message)
        local explicit = q:match("^riddle%s+") or q:match("^the riddle%s+") or q:match("^sammy asks%s+")
        local looksQuestion = explicit or message:find("?", 1, true)
            or q:match("^what%s+") or q:match("^which%s+") or q:match("^who%s+")
            or q:match("^when%s+") or q:match("^how%s+") or q:match("^where%s+")
        if not looksQuestion then return end
        questionBox.Text = message
        solve(message, true)
    end)
    status.Text = "Status: conectado aos anúncios do Sammy"
    return true
end

task.spawn(function()
    for _ = 1, 20 do
        if connectSammyRemote() then break end
        task.wait(2)
    end
end)

